  // Check that the widget responds to changes in UI density.

  function checkDensity(expectedRowHeight) {
    const tableRows = table.tBodies[1].rows;
    for (let i = 0; i < 7; i++) {
      Assert.equal(tableRows[0].clientHeight, expectedRowHeight);
